insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (1, 'Princeton University', '프린스턴 대학교', 1, 1, 1490, 1560, '신입생 72%가 고교 GPA 4.0 (CDS 2025-26 C11)', null, true, false, '{}', '최신 CDS(2025-26) C7에서 교과 난이도(rigor), 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 특별활동, 재능, 인성·개인 자질을 모두 Very Important로 공식 표시한다. 입학처 공식 페이지는 ''지적 호기심을 갖고 학업적 우수성을 추구해 온 학생''과 ''학교와 커뮤니티에서 변화를 만들어내는 학생''을 찾는다고 밝히고 있다.', 'https://ir.princeton.edu/document/606', 'test-optional', '미국 뉴저지주 프린스턴(Princeton, NJ)에 위치한 사립 종합대학으로, 교외(suburban) 주거형 단일 캠퍼스다.', '뉴욕과 필라델피아 사이의 소도시 대학 타운에 있으며, 두 대도시까지 기차로 약 1시간 거리이고 사계절이 뚜렷한 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (2, 'Massachusetts Institute of Technology', '매사추세츠 공과대학교 (MIT)', 2, 1, 1520, 1570, 'GPA 분포는 미공개(N/Av), 고교 석차 상위 10% 이내 신입생 97% (CDS 2025-26 C10)', 1.96, true, false, '{}', '입학처 공식 ''What we look for'' 페이지에서 MIT 미션(과학기술로 세상을 더 낫게)과의 정합성, 협업 정신, 주도성, 실패를 두려워하지 않는 도전, 손으로 직접 만드는 창의성, 소수의 관심사에 대한 진정한 몰입과 호기심, 삶의 균형을 명시한다. CDS 2025-26 C7에서 Very Important로 표시된 유일한 항목은 인성·개인 자질(character/personal qualities)이다.', 'https://ir.mit.edu/projects/2025-26-common-data-set/', 'test-required', '미국 매사추세츠주 케임브리지(Cambridge, MA)의 찰스강변에 위치한 사립 공과 중심 대학으로, 도시(urban) 캠퍼스다.', '보스턴 대도시권에 속해 찰스강 건너편이 보스턴 시내이며, 겨울이 춥고 눈이 잦은 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (3, 'Harvard University', '하버드 대학교', 3, 1, null, null, '신입생 74.7%가 고교 GPA 4.0 (CDS 2025-26 C11)', null, true, false, '{}', '입학처 공식 ''What We Look For'' 페이지에서 성장과 잠재력(자기 역량을 최대로 발휘해 왔는가), 관심사와 활동(무엇을 했고 무엇을 배웠는가), 인성(같이 지내고 싶은 사람인가), 하버드 커뮤니티에 대한 기여 가능성을 심사 기준으로 명시한다. 참고로 CDS 2025-26 C7에서는 어떤 요소도 Very Important로 표시하지 않고 대부분 Considered로만 표시한다.', 'https://oira.harvard.edu/files/2026/07/CDS_2025-2026.pdf', 'test-required', '미국 매사추세츠주 케임브리지(Cambridge, MA)에 위치한 사립 종합대학으로, 도시(urban) 캠퍼스다.', '보스턴 대도시권의 대학 도시 케임브리지에 있으며, 겨울이 춥고 눈이 잦은 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (4, 'Stanford University', '스탠퍼드 대학교', 4, 1, 1520, 1570, '신입생 73%가 고교 GPA 4.0 (CDS 2025-26 C11, 평균 GPA 3.94/4.0 unweighted)', null, false, false, '{}', '최신 CDS(2025-26) C7에서 교과 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 특별활동, 재능, 인성·개인 자질을 모두 Very Important로 공식 표시한다. 입학처 공식 FAQ는 학업적 탁월성과 함께 GPA·점수만으로는 드러나지 않는 지적 활력(intellectual vitality), 교내외 활동에서의 지속적 헌신과 리더십을 평가한다고 밝힌다.', 'https://irds.stanford.edu/data-findings/cds', 'test-required', '미국 캘리포니아주 스탠퍼드(Stanford, CA, 팰로앨토 인접)에 위치한 사립 종합대학으로, 넓은 교외(suburban)형 캠퍼스다.', '샌프란시스코 베이 에리어의 실리콘밸리 중심부에 있으며, 연중 온화하고 건조한 캘리포니아 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (5, 'Yale University', '예일 대학교', 4, 1, 1480, 1560, 'GPA 분포는 미공개, 고교 석차 상위 10% 이내 신입생 97% (CDS 2025-26 C10)', null, true, false, '{}', '입학처 공식 ''What Yale Looks For'' 페이지는 ''예일의 자원을 가장 잘 활용할 사람''과 ''예일 커뮤니티에 가장 크게 기여할 사람''이라는 두 질문을 심사의 축으로 명시하고, 학업 잠재력(탐구심 있는 명민한 지성), 타인에 대한 배려와 공동선에 대한 관심, 자기 역량을 확장하려는 탐구 의지를 든다. CDS 2025-26 C7에서는 교과 난이도, 석차, GPA, 에세이, 추천서, 특별활동, 재능, 인성을 Very Important로 표시한다(표준화 시험은 Considered).', 'https://oir.yale.edu/sites/default/files/yale_cds_2025-26_md_20260616.pdf', 'test-required', '미국 코네티컷주 뉴헤이븐(New Haven, CT)에 위치한 사립 종합대학으로, 중소도시 도심(urban)에 자리한 주거형(기숙 칼리지) 캠퍼스다.', '뉴욕에서 기차로 약 2시간 거리의 항구 중소도시이며, 사계절이 뚜렷한 미국 북동부 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (6, 'University of Chicago', '시카고대학교', 6, 1, null, null, null, null, null, null, '{}', '입학처 공식 지원 페이지는 ''학업·활동 기록, 에세이, 추천서, SAT/ACT 점수 등 어느 한 가지 요소만으로 합격 여부가 결정되지 않는다''고 명시하며, 지원자가 자신의 목소리로 자기 이야기를 보여줄 것을 강조합니다. 시험은 test-optional ''No Harm'' 정책으로, 점수는 유리하게 작용할 때만 심사에 반영된다고 공식 안내합니다.', 'https://collegeadmissions.uchicago.edu/apply/', 'test-optional', '일리노이주 시카고 남부 하이드파크(Hyde Park) 지역에 위치한 도시형 캠퍼스입니다.', '미국 3대 도시인 시카고 도심에서 남쪽으로 약 11km, 미시간 호수 인근에 있으며 겨울이 추운 편입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (7, 'Duke University', '듀크 대학교', 7, 1, 1510, 1570, null, null, false, true, '{"engineering"}', '공식 ''What We Look For'' 페이지에서 야망과 호기심, 재능과 끈기, 에너지와 인간미(ambition and curiosity, talent and persistence, energy and humanity)를 찾는다고 밝히며, 교과 난이도·성적·추천서·활동·에세이 5가지를 평가 요소로 명시한다. CDS 2025-26 C7 기준 Very Important는 교과 이수 난이도, GPA, 추천서, 특별활동, 재능/능력, 인성/개인 자질이다. (출처: admissions.duke.edu/what-we-look-for + CDS C7)', 'https://ir.provost.duke.edu/sites/default/files/CDS_PDF_2025-2026-20260622-website-published-version.pdf', 'test-optional', '노스캐롤라이나주 더럼의 교외형 캠퍼스를 가진 사립 종합대학이다.', '인구 약 28만의 중견 도시 더럼에 있으며, 리서치 트라이앵글 지역에 속하고 숲으로 둘러싸인 넓은 고딕 양식 캠퍼스다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (8, 'Johns Hopkins University', '존스 홉킨스 대학교', 7, 1, 1530, 1565, '신입생 66.1%가 GPA 4.0, 평균 GPA 3.93 (CDS 2025-26 C11·C12)', null, false, false, '{"engineering"}', '공식 FAQ에서 지원서 전반에 걸쳐 학업적 성격(academic character), 임팩트와 주도성(impact and initiative), 학교와의 전반적 적합성(overall match)을 본다고 명시한다. CDS 2025-26 C7 기준 Very Important는 교과 이수 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서다. (출처: apply.jhu.edu FAQ + CDS C7)', 'https://oira.jhu.edu/wp-content/uploads/2025-2026-CDS-Johns-Hopkins-University-v2.pdf', 'test-required', '메릴랜드주 볼티모어 북부 주거지역에 있는 사립 연구중심대학(학부는 Homewood 캠퍼스)이다.', '인구 약 57만의 대도시 볼티모어에 있으며, 도심에서 북쪽으로 떨어진 녹지형 캠퍼스이고 워싱턴 D.C.까지 차로 약 1시간 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (9, 'Northwestern University', '노스웨스턴 대학교', 7, 1, 1510, 1560, null, null, false, true, '{"engineering","arts","social_sci"}', '공식 입학처는 접근성(college access)에 대한 약속과 결합된 전체론적 검토를 강조하며, 성적·교과 난이도·추천서·수상 실적·에세이를 지원자의 학교·환경 맥락 속에서 평가한다고 밝힌다. CDS 2024-25 C7 기준 Very Important는 교과 이수 난이도, 석차, GPA, 에세이, 추천서, 특별활동, 재능/능력, 인성/개인 자질이다. (출처: admissions.northwestern.edu + CDS C7)', 'https://enrollment.northwestern.edu/data/2024-2025.pdf', 'test-optional', '일리노이주 에번스턴의 미시간 호숫가에 캠퍼스를 둔 사립 종합대학이다.', '시카고 도심에서 북쪽으로 약 20km 떨어진 교외 도시 에번스턴(인구 약 7.5만)에 있으며, 호수에 면한 캠퍼스로 겨울이 춥고 바람이 강한 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (10, 'University of Pennsylvania', '펜실베이니아 대학교(유펜)', 7, 1, 1510, 1560, '신입생 59%가 GPA 4.0, 평균 GPA 3.9 (CDS 2024-25 C11·C12)', null, false, false, '{"engineering","business"}', '공식 ''What Penn Looks For'' 페이지는 전인적 검토(whole-person review)를 통해 벤저민 프랭클린의 정신 — 개방적이고 호기심 많으며 창의적이고 실용적이며 분야를 넘나드는 연결 — 과 사회에 대한 기여(service to society)를 지향하는 학생을 찾는다고 밝힌다. CDS 2024-25 C7 기준 Very Important는 교과 이수 난이도, GPA, 에세이, 추천서, 인성/개인 자질이다. (출처: admissions.upenn.edu What Penn Looks For + CDS C7)', 'https://admissions.upenn.edu/how-to-apply/resources-programs/incoming-class-profile', 'test-required', '펜실베이니아주 필라델피아 도심 서쪽 University City 지구에 캠퍼스를 둔 아이비리그 사립대학이다.', '인구 약 160만의 대도시 필라델피아 시내에 있는 도심형 캠퍼스로, 뉴욕과 워싱턴 D.C. 사이에 위치하며 사계절이 뚜렷한 기후다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (11, 'California Institute of Technology (Caltech)', '캘리포니아 공과대학교(칼텍)', 11, 1, null, null, '석차 제출자 기준 신입생 86.4%가 고교 상위 10% (CDS 2024-25 C10)', null, false, false, '{}', 'CDS 2024-25 C7에서 교과 이수 난이도(rigor), 표준화 시험 점수, 에세이, 추천서, 인성/개인 자질을 Very Important로 명시한다. 공식 ''What We Look For'' 페이지는 고급 수학이 요구하는 추상적 사고와 문제 해결 능력을 중시하며, 정해진 ''칼텍형 학생''은 없고 각자의 학교·지역·기회라는 맥락 속에서 지원서를 평가한다고 밝힌다. (출처: admissions.caltech.edu What We Look For + CDS C7)', 'https://www.admissions.caltech.edu/apply/what-we-look-for', 'test-required', '캘리포니아주 패서디나(로스앤젤레스 인근)의 교외 주거지역에 있는 소규모 이공계 중심 사립대학이다.', 'LA 도심에서 북동쪽으로 약 17km 떨어진 중소도시 패서디나에 있으며, 연중 온화하고 건조한 남캘리포니아 기후의 컴팩트한 캠퍼스다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (12, 'Cornell University', '코넬대학교', 12, 1, 1510, 1560, '석차 제출 신입생(전체의 18.3%) 중 85.6%가 고교 상위 10% (CDS 2024-25 C10)', null, false, false, '{"cs","engineering","business","math_data","natural_sci","social_sci","humanities","arts"}', 'CDS 2024-25 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도(rigor), 에세이, 추천서, 교외 활동(extracurricular activities), 재능(talent/ability), 인성(character/personal qualities)입니다. 석차·GPA는 Important, 시험 점수는 Considered입니다. 입학처는 시험 점수를 GPA·교과 난이도·활동·에세이·추천서 등 다른 자료와 함께 맥락 속에서 본다고 공식 명시하며, 8개 칼리지 중 하나에 직접 지원하는 구조라 지원 칼리지별 에세이와 요건이 다릅니다.', 'https://irp.dpb.cornell.edu/wp-content/uploads/2025/07/CDS-2024-2025-v6-print.pdf', 'test-required', '뉴욕주 이타카(Ithaca)의 소도시에 위치하며, 언덕 위에 자리한 넓은 전원형 캠퍼스입니다.', '이타카는 인구 약 3만의 대학 도시로 뉴욕시에서 차로 약 4시간 거리이며, 겨울이 길고 추운 편입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (13, 'Brown University', '브라운대학교', 13, 1, 1470, 1550, '석차 제출 신입생(전체의 29.3%) 중 93%가 고교 상위 10% (CDS 2025-26 C10)', null, true, false, '{}', 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 재능(talent/ability), 인성입니다. 교외 활동은 Important, 인터뷰와 지원자 관심도는 Not Considered입니다. 입학처는 시험 점수를 ''각 학생이 지원하는 개인적 맥락(individual context)에 근거해'' 평가한다고 공식 명시합니다.', 'https://web.archive.org/web/20260429124047/https://oir.brown.edu/sites/default/files/2020-04/CDS-PDF-2025-2026.pdf', 'test-required', '로드아일랜드주 프로비던스(Providence)의 칼리지 힐 지역에 위치한 도시형 캠퍼스입니다.', '프로비던스는 인구 약 19만의 중소 도시로 보스턴에서 차로 약 1시간 거리에 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (14, 'Dartmouth College', '다트머스칼리지', 13, 1, 1440, 1550, '석차 제출 신입생(전체의 44%) 중 96%가 고교 상위 10% (CDS 2025-26 C10)', null, true, true, '{}', 'CDS 2025-26 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도, 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 교외 활동, 인성입니다. 5개 대학 중 유일하게 지원자 관심도(Level of applicant''s interest)가 ''Considered''로 공식 표기되어 있습니다. 시험 점수는 최고 섹션 점수 조합(superscore)으로 평가한다고 입학처가 공식 안내합니다.', 'https://www.dartmouth.edu/oir/pdfs/cds_2025-26.pdf', 'test-required', '뉴햄프셔주 하노버(Hanover)의 소도시에 위치한 전원형 캠퍼스입니다.', '하노버는 인구 약 1만의 작은 대학 마을로 자연에 둘러싸여 있으며 겨울이 길고 눈이 많습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (15, 'Columbia University', '컬럼비아대학교', 15, 1, 1510, 1560, '석차 제출 신입생(전체의 25.7%) 중 94%가 고교 상위 10% (CDS 2024-25 C10)', null, false, false, '{"engineering"}', 'CDS 2024-25 C7에서 ''Very Important''로 공식 표기한 항목은 교과 난이도, 석차, GPA, 에세이, 추천서, 교외 활동, 인성입니다. 시험 점수는 Considered, 지원자 관심도는 Not Considered입니다. 입학처는 ''학업 우수성(academic excellence)을 기반으로 지원서 전체를 신중히 검토하는 전인적(holistic) 심사''와 개인의 상황·기회 요인 고려를 공식 명시합니다.', 'https://opir.columbia.edu/sites/opir.columbia.edu/files/content/Common%20Data%20Set/2024-25_Columbia_College_and_Columbia_Engineering_CDS.pdf', 'test-optional', '뉴욕시 맨해튼 모닝사이드 하이츠(Morningside Heights)에 위치한 도심형 캠퍼스입니다.', '미국 최대 도시 뉴욕 맨해튼 안에 있어 대중교통과 도시 인프라 접근성이 높은 환경입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (16, 'University of California, Berkeley', 'UC 버클리(캘리포니아대학교 버클리)', 15, 1, null, null, '2026년 가을 합격자의 고교 GPA 중간 50%는 4.16–4.28(가중 GPA)이며, CDS 2025-26 기준 재학 신입생 평균 고교 GPA는 3.90(4.0 만점)입니다.', 6, null, false, '{"engineering","cs","math_data","business"}', 'UC 공통 종합심사(comprehensive review) 13개 기준으로 평가하며, A-G 교과 GPA, 우등·AP·IB 과목 이수와 성적, 고교 여건 대비 성취, 특별한 재능·성취·리더십, 개인 환경을 고려한 학업 성취를 봅니다. CDS 2025-26 기준 ''매우 중요'' 요소는 교과 난이도·GPA·에세이(PIQ)이며, 특별활동·인성·봉사·직업 경험은 ''Important''입니다. (출처: UC ''How applications are reviewed'' 공식 페이지 및 UC Berkeley CDS 2025-26 C7)', 'https://admission.universityofcalifornia.edu/counselors/preparing-freshman-students/freshman-requirements.html', 'test-free', '캘리포니아주 버클리에 위치한 공립대학으로, 샌프란시스코만 동쪽의 도시형 캠퍼스입니다.', '버클리는 샌프란시스코에서 만 건너편에 있는 인구 약 12만 명의 대학 도시로, 연중 온화한 기후이며 대중교통(BART)으로 샌프란시스코와 연결됩니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (17, 'Rice University', '라이스 대학교', 17, 1, 1510, 1560, 'CDS 2025-26 기준 신입생의 90%가 고교 졸업 석차 상위 10% 이내입니다(GPA 분포는 미공개).', null, false, true, '{"arts"}', 'CDS 2025-26 기준 ''매우 중요'' 요소는 교과 난이도·석차·GPA·표준화 시험 점수·에세이·추천서·특별활동·재능·인성으로 폭넓습니다. 지원자의 관심도(Level of applicant''s interest)도 ''Considered''로 반영됩니다. 라이스는 시험 점수를 홀리스틱 리뷰의 여러 요소 중 하나로 본다고 공식적으로 밝히고 있습니다. (출처: Rice CDS 2025-26 C7·C8F, admission.rice.edu)', 'https://ideas.rice.edu/wp-content/uploads/2026/07/CDS_2025-26_WEBSITE.pdf', 'test-optional', '텍사스주 휴스턴의 뮤지엄 디스트릭트 인근에 위치한 사립 연구중심대학으로, 대도시 안의 녹지형 캠퍼스입니다.', '휴스턴은 미국 4위 규모의 대도시로 여름이 덥고 습한 아열대성 기후이며, 캠퍼스는 세계 최대 의료단지인 텍사스 메디컬 센터와 인접해 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (18, 'University of California, Los Angeles (UCLA)', 'UCLA(캘리포니아대학교 로스앤젤레스)', 17, 1, null, null, '2026년 가을 합격자의 고교 GPA 중간 50%는 4.20–4.30(가중 GPA 기준)입니다.', 6, null, false, '{"engineering","cs","arts","premed"}', 'UC 공통 종합심사(comprehensive review) 13개 기준으로 평가하며, A-G 교과 GPA, AP·IB 등 심화 과목 이수와 성적, 재학 고교의 여건 대비 성취도, 특별한 재능·수상·리더십 경험, 삶의 환경을 고려한 학업 성취 등을 봅니다. CDS 2025-26 기준 ''매우 중요(Very Important)'' 요소는 교과 난이도(rigor)·GPA·지원 에세이(PIQ)입니다. (출처: UC ''How applications are reviewed'' 공식 페이지 및 UCLA CDS 2025-26 C7)', 'https://admission.universityofcalifornia.edu/counselors/preparing-freshman-students/freshman-requirements.html', 'test-free', '미국 캘리포니아주 로스앤젤레스 웨스트우드(Westwood) 지역에 위치한 대형 공립대학으로, 도심형 캠퍼스입니다.', '로스앤젤레스는 미국에서 두 번째로 큰 도시로 연중 온화한 지중해성 기후이며, 캠퍼스는 태평양 연안에서 약 8km 떨어진 주거·상업 지역에 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (19, 'Vanderbilt University', '밴더빌트 대학교', 17, 1, 1510, 1560, 'CDS 2025-2026 기준 신입생 평균 고교 GPA는 3.90(4.0 만점)이고, 91%가 고교 석차 상위 10% 이내입니다.', null, false, false, '{"engineering","arts"}', 'CDS 2025-2026 기준 ''매우 중요'' 요소는 교과 난이도·석차·GPA·에세이·특별활동·인성(character/personal qualities)입니다. 표준화 시험 점수와 재능은 ''Important'', 추천서·인터뷰는 그보다 낮은 비중입니다. (출처: Vanderbilt CDS 2025-2026 C7)', 'https://www.vanderbilt.edu/dsa/common-data-set/', 'test-optional', '테네시주 내슈빌 도심 인근에 위치한 사립 연구중심대학으로, 캠퍼스 전체가 수목원으로 지정된 도시형 캠퍼스입니다.', '내슈빌은 음악 산업의 중심지로 알려진 인구 약 70만 명의 중형 도시이며, 캠퍼스는 다운타운에서 약 2.5km 거리에 있고 사계절이 뚜렷한 기후입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (20, 'Carnegie Mellon University', '카네기멜런대학교', 20, 1, 1500, 1560, '신입생 평균 고교 GPA 3.89이며 43.9%가 GPA 4.0, 82.5%가 고교 상위 10% 이내입니다 (CDS 2025-26 C10-C12).', null, false, false, '{"cs","engineering","business","math_data","natural_sci","social_sci","humanities","arts"}', '최신 CDS(2025-26) C7 기준으로 교육과정의 엄격함(rigor), 석차, GPA, 교외활동(extracurricular), 인성·개인 자질, 봉사활동을 ''Very Important''로 평가합니다. 에세이·추천서·재능·First generation 여부는 ''Important''이며, 표준화 시험 점수는 ''Considered''입니다. 전형 요소의 비중은 단과대(프로그램)별로 다르다고 공식 명시하고 있습니다.', 'https://www.cmu.edu/ira/CDS/pdf/cds_2025_26/cds-2025-c-first-time-first-year-admission.pdf', 'test-required', '펜실베이니아주 피츠버그(Pittsburgh)에 위치한 사립 연구중심 대학으로, 도심(Oakland 지역)에 캠퍼스가 있습니다.', '피츠버그는 미국 북동부의 중간 규모 도시로 사계절이 뚜렷하며, 캠퍼스는 피츠버그대학교 등과 인접한 대학가에 있습니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (21, 'University of Michigan--Ann Arbor', '미시간대학교 앤아버', 20, 1, 1370, 1530, '신입생 평균 고교 GPA 3.9이며 93.9%가 GPA 3.75 이상입니다 (CDS 2025-26 C11-C12).', null, false, true, '{"engineering","business","arts"}', 'CDS 2025-26 C7 기준 교육과정의 엄격함(rigor)과 GPA가 ''Very Important''이고, 시험 점수·에세이·추천서·인성·First generation 여부는 ''Important''입니다. 공식 Selection Process 페이지는 단일 기준이 아닌 전체적 검토(holistic review)를 명시하며, 엄격한 커리큘럼에서의 성취와 교실 밖 리더십·수상·봉사를 중요 평가 요소로 제시하고, 레거시(동문 자녀)는 고려하지 않는다고 밝힙니다.', 'https://obp.umich.edu/wp-content/uploads/pubdata/cds/cds_2025-26_umaa.pdf', 'test-optional', '미시간주 앤아버(Ann Arbor)에 위치한 주립 연구중심 대학으로, 대학 중심 중형 도시에 캠퍼스가 있습니다.', '앤아버는 디트로이트에서 서쪽으로 차로 약 45분 거리의 대표적인 대학 도시(college town)로, 겨울이 길고 추운 오대호 인근 기후입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (22, 'University of Notre Dame', '노트르담 대학교', 20, 1, 1460, 1540, 'CDS 2025-2026 기준 신입생의 92%가 고교 졸업 석차 상위 10% 이내입니다(GPA 분포는 미공개).', null, true, false, '{"business"}', '공식 평가 기준 페이지에서 고교 여건 내 가장 도전적인 교과 이수와 성적, ''이끌고 영향을 만드는(leading and making an impact)'' 특별활동, 교과 교사·카운슬러 추천서, 그리고 지원자의 실제 모습을 보여주는 에세이를 강조합니다. CDS 2025-2026 기준 교과 난이도·석차·GPA·에세이·추천서·특별활동·재능·인성·봉사활동이 ''매우 중요''이며 표준화 시험 점수는 ''Important''입니다. (출처: admissions.nd.edu Evaluation Criteria 및 ND CDS 2025-2026 C7)', 'https://iris.nd.edu/institutional-research/common-data-set-cds/common-data-set/', 'test-optional', '인디애나주 사우스벤드 인근 노터데임(Notre Dame)에 위치한 가톨릭 사립대학으로, 교외형 캠퍼스입니다.', '시카고에서 동쪽으로 약 150km 떨어진 인구 약 10만 명의 소도시권에 있으며, 겨울에 춥고 눈이 많은 오대호 인접 기후입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (23, 'Washington University in St. Louis', '세인트루이스 워싱턴대학교', 20, 1, 1500, 1570, '신입생 평균 고교 GPA는 4.19(제출자 90% 기준, 학교 제출 스케일 그대로)이며 86%가 고교 상위 10% 이내입니다 (CDS 2024-25 C10-C12).', null, false, true, '{"engineering","business","arts"}', 'CDS 2024-25 C7 기준 교육과정의 엄격함(rigor), 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 재능(talent/ability), 인성·개인 자질이 모두 ''Very Important''로 표시되어 있습니다. 교외활동·First generation·봉사·직업 경험은 ''Important'', 지원자의 관심도(demonstrated interest)는 ''Considered''입니다. 출처는 WashU 공식 Common Data Set 2024-25 C7입니다.', 'https://washu.edu/app/uploads/2025/06/2024-2025-WashU-CDS.pdf', 'test-optional', '미주리주 세인트루이스(St. Louis) 인근 교외에 위치한 사립 연구중심 대학으로, 주 캠퍼스(Danforth Campus)는 대형 도시공원인 Forest Park와 인접해 있습니다.', '세인트루이스는 미국 중서부의 중간 규모 도시이며, 캠퍼스는 도심이 아닌 시 서쪽 경계의 교외 주거 지역에 있어 상대적으로 조용한 환경입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (24, 'Emory University', '에모리 대학교', 24, 2, 1480, 1540, '신입생 평균 고교 GPA 3.80, 63%가 3.75-3.99 구간, 상위 10% 이내 76% (CDS 2025-26 C10-C12).', 6.3, null, false, '{}', '최신 CDS(2025-26) C7에서 교과 과정의 도전성(rigor), 내신 GPA, 과외활동, 재능/특기, 인성·개인적 자질을 ''매우 중요(Very Important)''로 공식 보고. 에세이·추천서·봉사활동과 (제출 시) 표준화 시험 점수는 ''중요(Important)'' 등급.', 'https://provost.emory.edu/planning-administration/_includes/documents/sections/institutional-data/emory-common-date-set-2025-2026.pdf', 'test-optional', '조지아주 애틀랜타에 위치한 사립 연구중심 대학으로, 학부 지원은 에모리 칼리지와 옥스퍼드 칼리지 두 캠퍼스로 나뉜다.', '애틀랜타 대도시권 주거지역(드루이드 힐스)의 교외형 캠퍼스로, 여름이 덥고 겨울이 온화한 미국 남부 기후.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (25, 'Georgetown University', '조지타운 대학교', 24, 2, 1405, 1530, '신입생의 87%가 고교 상위 10%, 97%가 상위 25% 이내 (CDS 2025-26 C10; GPA 분포·평균 미공개).', 8.3, null, false, '{"business","social_sci","premed"}', 'CDS 2025-26 C7 기준 교과 rigor, 석차, GPA, 표준화 시험 점수, 에세이, 추천서, 재능/특기, 인성을 모두 ''매우 중요(Very Important)''로 평가 — 학업 요소 전반을 최상위로 보는 구조. 인터뷰와 과외활동은 ''중요(Important)'' 등급이며, SAT/ACT 제출이 여전히 필수인 소수 대학 중 하나.', 'https://georgetown.box.com/s/0r8akn4cbm52zjkll6i7uttlb9k36px2', 'test-required', '워싱턴 D.C.에 위치한 미국에서 가장 오래된 가톨릭(예수회) 사립대학으로, 학부가 6개 스쿨로 나뉘어 있다.', '워싱턴 D.C. 북서부 조지타운 지구의 도시형 캠퍼스로, 사계절이 뚜렷한 기후이며 연방정부·국제기구와 가깝다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (26, 'University of North Carolina at Chapel Hill', '노스캐롤라이나 대학교 채플힐', 26, 2, 1400, 1530, '신입생 평균 고교 GPA 4.47(가중 기준), 94.6%가 가중 4.0 이상, 상위 10% 이내 76.2% (CDS 2025-26 C10-C12).', 15.0, null, false, '{"business"}', 'CDS 2025-26 C7 기준 교과 rigor, 에세이, 추천서, 과외활동, 재능/특기, 인성, 그리고 주(州) 거주 여부를 ''매우 중요(Very Important)''로 평가 — 공립대 특성상 노스캐롤라이나 주민 우대가 공식 명시됨. 시험 점수는 ''고려(Considered)'', GPA·석차는 ''중요(Important)'' 등급.', 'https://oira.unc.edu/wp-content/uploads/sites/297/2026/06/CDS_UNCCH_2025-26_20260615.pdf', 'test-optional', '노스캐롤라이나주의 공립 플래그십 대학으로, 미국에서 가장 오래된 공립대학 중 하나다.', '채플힐은 대학 중심의 소도시(칼리지 타운)로, 롤리·더럼과 함께 리서치 트라이앵글 지역을 이루며 기후가 온화하다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (27, 'University of Virginia', '버지니아 대학교', 26, 2, 1410, 1520, '신입생의 90.5%가 고교 GPA 4.0(제출 기준), 상위 10% 이내 84% (CDS 2024-25 C10-C11; 평균 GPA 미공개).', 10.5, false, false, '{"engineering","cs","premed","arts"}', 'CDS 2024-25 C7 기준 교과 rigor, 고교 석차, GPA, 인성·개인적 자질, 주(州) 거주 여부를 ''매우 중요(Very Important)''로 평가 — 공립대로서 버지니아 주민 우대가 공식 명시됨. 에세이·추천서·과외활동·재능은 ''중요(Important)'', 시험 점수는 ''고려(Considered)'' 등급.', 'https://ira.virginia.edu/sites/ira/files/2025-03/CDS_2024-2025_508.pdf', 'test-optional', '토머스 제퍼슨이 설립한 버지니아주의 공립 플래그십 대학으로, 캠퍼스 일부가 유네스코 세계문화유산이다.', '샬러츠빌은 워싱턴 D.C.에서 차로 약 2시간 반 거리의 소도시형 대학도시로, 사계절이 뚜렷한 기후.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (28, 'University of Southern California', '서던캘리포니아 대학교 (USC)', 28, 2, 1470, 1540, '신입생 평균 고교 GPA 3.85, 4.0 만점자 28.2%, 3.75-3.99 구간 52% (CDS 2025-26 C11-C12).', 13.7, null, false, '{"cs","engineering","business","arts"}', 'CDS 2025-26 C7 기준 교과 rigor, 내신 GPA, 에세이, 추천서, 인성·개인적 자질을 ''매우 중요(Very Important)''로 평가. 과외활동과 재능/특기는 ''중요(Important)'' 등급이며, 석차·인터뷰·지원자 관심도는 반영하지 않는다고 공식 보고.', 'https://oir.usc.edu/common-data-set-archive/common-data-set-2025-2026/', 'test-optional', '로스앤젤레스에 위치한 캘리포니아에서 가장 오래된 사립 연구중심 대학으로, 지원 시 전공·스쿨 단위로 선발한다.', 'LA 다운타운 인근 University Park의 도시형 캠퍼스로, 연중 온화하고 건조한 지중해성 기후.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (29, 'University of California, San Diego', '캘리포니아대학교 샌디에이고 (UC 샌디에이고)', 29, 2, null, null, 'CDS 2025-2026 기준 Fall 2025 입학생 평균 고교 GPA 3.88, 85%가 3.75 이상이다.', 29, null, false, '{"cs","engineering","math_data","premed"}', 'CDS 2025-2026 C7 기준 ''매우 중요(Very Important)'' 요소는 교과 이수 강도(rigor), 학업 GPA, 지원 에세이(PIQ) 세 가지다. 시험 점수·추천서·인터뷰는 아예 고려하지 않으며, 과외활동·재능·인성은 ''Important'' 수준으로 본다.', 'https://ir.ucsd.edu/stats/undergrad/CDS_2024-2025_Final1.pdf', 'test-free', '캘리포니아대학교(UC) 시스템 소속의 연구 중심 공립 대학으로, STEM과 바이오·데이터 분야가 특히 강하다.', '캘리포니아주 샌디에이고 라호야(La Jolla) 해안 지역에 캠퍼스가 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (30, 'University of Florida', '플로리다대학교', 30, 2, 1330, 1470, 'CDS 2024-2025 기준 Fall 2024 입학생 평균 고교 GPA 3.92, 53%가 4.0이다.', null, null, false, '{}', 'CDS 2024-2025 C7 기준 ''매우 중요(Very Important)'' 요소는 교과 이수 강도(rigor), 학업 GPA, 과외활동, 재능/능력(talent/ability)이다. 시험 점수와 에세이는 ''Important'', 추천서와 지원자의 관심도는 고려하지 않는다.', 'https://data-apps.ir.aa.ufl.edu/public/cds/CDS_2024-2025_UFMAIN_Post_v1.pdf', 'test-required', '플로리다주의 대표 주립 플래그십 대학으로, 대형 종합 연구 대학이다.', '플로리다주 게인즈빌(Gainesville)에 있는 대학 도시 캠퍼스다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (31, 'University of Texas at Austin', '텍사스대학교 오스틴', 30, 2, null, null, null, null, null, false, '{"cs","engineering","business","math_data","natural_sci","premed","social_sci","humanities","arts"}', '공식 입학처 심사 안내 기준으로 석차(class rank), 교과 이수 강도, 시험 점수, 수상·성취 기록, 활동·봉사, 에세이를 종합 심사(holistic review)하며, 지원 전공의 경쟁률도 함께 본다. CDS 2025-2026 C7에서는 특정 요소를 ''매우 중요''로 지정하지 않고 학업·비학업 요소 대부분을 ''Considered''로 표시했다.', 'https://admissions.utexas.edu/apply/review-decision-process/', 'test-required', '텍사스주의 플래그십 주립 대학으로 CS·공학·비즈니스(McCombs) 등 전공 단위 선발 경쟁이 치열하다.', '텍사스주 주도 오스틴(Austin) 도심에 캠퍼스가 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (32, 'Georgia Institute of Technology', '조지아공과대학교 (조지아텍)', 32, 2, 1370, 1530, 'CDS 2025-2026 기준 Fall 2025 입학생 평균 고교 GPA 4.17이며 95.9%가 4.0 이상이다.', null, null, false, '{}', 'CDS 2025-2026 C7 기준 ''매우 중요(Very Important)'' 요소는 교과 이수 강도(rigor), 학업 GPA, 인성/개인 자질, 주(조지아) 거주 여부다. 에세이와 과외활동은 ''Important''이며, 지원 전공에 대한 관심과 준비의 증거를 심사에 반영한다(공식 Major Selection 페이지).', 'https://irp.gatech.edu/files/CDS/CDS_2025-2026_FINAL_R3_30MAR2026.pdf', 'test-required', '공학·컴퓨팅 중심의 미국 대표 공과 주립대학으로, 실무·연구 양면에서 STEM 특화가 뚜렷하다.', '조지아주 애틀랜타(Atlanta) 미드타운에 캠퍼스가 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (33, 'New York University', '뉴욕대학교 (NYU)', 32, 2, 1480, 1550, 'CDS 2025-2026 기준 Fall 2025 입학생 평균 고교 GPA 3.81, 71.9%가 3.75 이상이다.', null, null, true, '{"business","engineering","arts"}', 'CDS 2025-2026 C7 기준 ''매우 중요(Very Important)'' 요소는 교과 이수 강도(rigor), 학업 GPA, 에세이, 추천서, 인성/개인 자질이다. 시험 점수는 ''Important''이며, 지원자의 관심도(demonstrated interest)와 과외활동·재능은 ''Considered''로 반영된다.', 'https://www.nyu.edu/content/dam/nyu/institutionalResearch/documents/cds-2025-2026/CDS%202025-2026%20FINAL%20(no%20G).pdf', 'test-optional', '뉴욕 맨해튼 도심에 자리한 대형 사립 종합대학으로, 스쿨(단과대) 단위로 지원하는 구조다.', '뉴욕주 뉴욕시 맨해튼 그리니치빌리지 일대에 도시형 캠퍼스가 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (34, 'University of California, Davis', '캘리포니아대학교 데이비스 (UC 데이비스)', 32, 2, null, null, 'Fall 2025 입학생 평균 고교 GPA 4.03(가중), 66.1%가 GPA 4.0 (CDS C11-C12)', 56, null, false, '{"cs","engineering","math_data","natural_sci","social_sci","humanities","arts"}', 'UC 공식 종합평가(comprehensive review) 13개 기준에 따라 A-G 과목 GPA, 이수 과목의 폭과 난이도(Honors·AP·IB), 학교 환경 대비 성취도, 특정 분야의 탁월한 성과·재능, 성적 상승 추세, 가정·학교 여건 등 맥락을 함께 평가한다. CDS 2025-2026 C7 기준 Very Important는 교육과정의 엄정성(rigor)과 학업 GPA이며, 에세이·활동·재능·인성은 Important다.', 'https://aggiedata.ucdavis.edu/sites/g/files/dgvnsk1841/files/media/documents/CDS_UCD_0.pdf', 'test-free', '캘리포니아대학교(UC) 시스템 소속 공립 연구중심 대학이다.', '캘리포니아주 데이비스(주도 새크라멘토 인근)에 위치한다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (35, 'University of California, Irvine', '캘리포니아대학교 어바인 (UC 어바인)', 32, 2, null, null, null, 42, null, false, '{"cs","engineering","business","math_data","natural_sci","premed","social_sci","humanities","arts"}', 'UC 공식 종합평가(comprehensive review) 13개 기준으로 A-G 과목 GPA, 이수 과목의 난이도, 학교 여건 대비 성취, 특별한 재능과 성과, 성적 상승 추세 등을 맥락과 함께 평가한다. CDS 2024-2025 C7 기준 Very Important는 교육과정의 엄정성, 학업 GPA, 에세이, 교외 활동, 재능/능력, 봉사활동, 직업 경험으로 활동 영역의 비중이 큰 편이다.', 'https://bpb-us-e2.wpmucdn.com/sites.uci.edu/dist/2/5478/files/2026/05/2025-26-CDS-PDF-Upload.pdf', 'test-free', '캘리포니아대학교(UC) 시스템 소속 공립 연구중심 대학이다.', '캘리포니아주 오렌지카운티 어바인에 위치한다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (36, 'Boston College', '보스턴 칼리지', 36, 2, 1460, 1520, 'Fall 2024 입학생 중 고교 석차 제출자(27%)의 90%가 상위 10% 출신 (CDS C10; GPA 분포·평균 미보고)', null, null, false, '{"business","premed"}', 'CDS 2024-2025 C7 기준 Very Important는 교육과정의 엄정성(rigor)과 학업 GPA 두 가지다. 공식 test-optional 페이지는 성적, 교육과정 난이도, 글쓰기, 교내외 활동, 추천서를 함께 보는 홀리스틱 리뷰를 명시하며 ''점수는 여러 요소 중 하나일 뿐 단독 결정 요인이 아니다''라고 밝힌다.', 'https://www.bc.edu/content/dam/bc1/offices/irp/ir/cds/Boston_College_CDS_2024-2025_Final.pdf', 'test-optional', '1863년 설립된 예수회(Jesuit) 전통의 사립 연구대학이다.', '매사추세츠주 보스턴 근교 체스트넛힐에 위치한다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (37, 'Tufts University', '터프츠 대학교', 36, 2, 1460, 1520, 'Fall 2025 입학생 중 고교 석차 제출자(21%)의 87%가 상위 10% 출신 (CDS C10; GPA 분포·평균 미보고)', null, null, true, '{"engineering","arts"}', 'CDS 2025-2026 C7 기준 Very Important는 교육과정의 엄정성, 학급 석차, 학업 GPA, 에세이, 추천서, 인성/개인 자질이다. 교외 활동과 재능은 Important, 지원자의 관심도(demonstrated interest)와 인터뷰는 Considered로 반영된다.', 'https://provost.tufts.edu/institutionalresearch/wp-content/uploads/sites/5/CDS_2025-2026.pdf', 'test-optional', '1852년 설립된 보스턴 인근의 사립 연구대학이다.', '매사추세츠주 메드퍼드/서머빌(보스턴 근교)에 위치한다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (38, 'University of Illinois Urbana-Champaign', '일리노이대학교 어바나-샴페인 (UIUC)', 36, 2, 1390, 1520, 'Fall 2025 입학생 중 고교 석차 제출자(21.7%)의 61.6%가 상위 10%, 88.8%가 상위 25% 출신 (CDS C10; 평균 GPA 미보고)', null, null, false, '{"cs","engineering","business","math_data","natural_sci","social_sci","humanities","arts"}', 'CDS 2025-2026 C7 기준 Very Important는 교육과정의 엄정성(rigor)과 학업 GPA다. 에세이는 Important, 시험 점수·교외 활동·재능은 Considered이며, 전공 단위 선발이므로 지원 전공과 관련된 준비가 사실상 핵심 평가 맥락이 된다.', 'https://www.dmi.illinois.edu/stuenr/misc/cds_2025_2026.xlsx', 'test-optional', '1867년 설립된 일리노이주의 플래그십 공립 연구대학이다.', '일리노이주 어바나-샴페인 트윈시티에 위치하며 시카고에서 남쪽으로 약 220km 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (39, 'University of Wisconsin--Madison', '위스콘신 대학교 매디슨', 36, 2, 1370, 1490, 'Fall 2024 입학생 평균 고교 GPA 3.90, 52.7%가 GPA 4.0 (CDS C11-C12)', null, false, false, '{"engineering","business"}', 'CDS 2024-2025 C7 기준 Very Important는 교과과정 난이도(rigor)와 학업 GPA 두 가지뿐이며, 시험 점수·과외활동은 그보다 낮은 단계다. 공식 입학처 페이지(What We Look For)는 도전적 과목(Honors·AP·IB)에서의 최상위 성적, 에세이를 통한 개인 스토리, 리더십과 커뮤니티 기여를 종합 평가한다고 밝힌다.', 'https://uwmadison.box.com/s/cm3r7gc83w3eqjotfbva111dnin6toer', 'test-optional', '위스콘신주의 주립 플래그십 연구 대학으로 학부생 약 3만 8천 명 규모의 대형 종합대학이다.', '위스콘신주 주도 매디슨에 위치하며 호수로 둘러싸인 대학 도시형 캠퍼스다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (40, 'University of California, Santa Barbara', '캘리포니아 대학교 샌타바버라 (UC 샌타바버라)', 40, 2, null, null, 'Fall 2025 입학생 평균 고교 GPA 4.29(가중), 87.8%가 GPA 4.0 (CDS 2025-26 C11-C12)', null, null, false, '{"cs","engineering"}', 'UC 공통 종합평가(comprehensive review) 13개 요소로 성취를 기회·환경 맥락에서 평가한다고 공식 페이지에 명시한다. CDS 2025-26 C7 기준 Very Important는 학업 GPA와 지원 에세이이며, 시험 점수·추천서·인터뷰는 아예 고려하지 않는다.', 'https://admissions.sa.ucsb.edu/freshman-eligibility-selection', 'test-free', '캘리포니아 해안 샌타바버라에 위치한 UC 계열 연구 중심 주립대학으로 3개 단과대학에 85개 전공을 운영한다.', '캘리포니아주 샌타바버라 해안에 위치하며 로스앤젤레스에서 북서쪽으로 약 150km 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (41, 'Ohio State University', '오하이오 주립 대학교', 41, 3, 1280, 1430, 'Fall 2024 입학생의 64%가 고교 상위 10%, 95%가 상위 25% (CDS C10; GPA 분포 미공개)', null, false, false, '{}', 'CDS 2024-2025 C7 기준 Very Important는 교과 난이도(rigor)·석차·GPA·표준화시험 점수 4가지로, 학업 지표 중심의 평가다. 공식 입학처 페이지(Who Gets In)는 리더십과 활동 참여, 다양한 캠퍼스 공동체에 대한 기여 가능성, 협업·회복탄력성 같은 개인 자질도 검토한다고 명시한다.', 'https://irp.osu.edu/sites/default/files/documents/2025/11/CDS-2024-2025-The-Ohio-State-University-Columbus.pdf', 'test-required', '오하이오주 콜럼버스에 위치한 대형 주립 플래그십 연구 대학으로 미국 최대 규모급 단일 캠퍼스를 운영한다.', '오하이오주 주도 콜럼버스 시내 인근에 위치한다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (42, 'Boston University', '보스턴 대학교', 42, 3, 1430, 1510, 'Fall 2024 입학생 평균 고교 GPA 3.9, 78%가 GPA 3.75 이상 (CDS C11-C12)', null, false, true, '{"business","engineering","arts","cs","math_data"}', 'CDS 2024-2025 C7 기준 Very Important는 교과 난이도(rigor)와 학업 GPA이며, 에세이·추천서·과외활동·인성은 Important 단계다. 지원자의 관심도(demonstrated interest)가 Considered로 반영되는 점이 특징이고, CFA(예술대) 지원자는 실기·포트폴리오가 매우 중요하다고 명시한다.', 'https://www.bu.edu/asir/files/2025/03/cds-2025-c.pdf', 'test-optional', '보스턴 찰스강변에 위치한 대형 사립 연구 대학으로 10여 개 학부 단과대학을 운영한다.', '매사추세츠주 보스턴 도심의 도시형 캠퍼스다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (43, 'Rutgers University--New Brunswick', '럿거스 대학교 뉴브런즈윅', 42, 3, 1350, 1510, 'Fall 2025 정규 입학허가자(SAS) 고교 GPA 중간 50%는 3.8-4.2 (학교별 상이: 공대 3.9-4.3, 약대 4.0-4.3)', null, null, false, '{"engineering","business","arts","premed","natural_sci"}', 'CDS 2023-2024 C7 기준 Very Important는 교과 난이도(rigor)와 학업 GPA이며, 추천서·인터뷰·지원자 관심도는 고려하지 않는다. 공식 입시 프로필(Fall 2025)은 학업 성취와 성적, 에세이, 과외활동, 지원 학교 선택 등을 종합 검토(holistic review)한다고 명시한다.', 'https://admissions.rutgers.edu/sites/default/files/2025-07/2025%20Desk%20Reference%20Card%20FINAL%20QR.pdf', 'test-optional', '뉴저지주의 주립 플래그십 대학으로 뉴브런즈윅이 메인 캠퍼스다.', '뉴저지주 뉴브런즈윅에 위치하며 뉴욕 맨해튼에서 기차로 약 1시간 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (44, 'University of Maryland, College Park', '메릴랜드 대학교 칼리지파크', 42, 3, 1410, 1520, 'Fall 2025 신입생의 평균 고교 GPA는 4.41(가중 산출)이고 89.2%가 GPA 4.0이다 (CDS 2025-26 C11-C12).', null, null, false, '{"cs","engineering","business","natural_sci","social_sci","arts"}', 'CDS 2025-26 C7에서 Very Important는 고교 교과 과정의 엄격성(rigor) 하나뿐이다. 공식 입학처 페이지는 23개 이상의 요소를 보는 홀리스틱 리뷰를 명시하며, 성적·커리큘럼 수준 외에 에세이, 리더십, 지역사회 활동, 가정·환경적 맥락까지 함께 평가한다고 밝힌다.', 'https://www.irpa.umd.edu/InstitutionalData/CommonDataSet/CDS_2025-2026.xlsx', 'test-optional', '메릴랜드주의 플래그십 주립대학으로 CS·공학 등 STEM 분야가 강한 대형 연구 중심 대학이다.', '메릴랜드주 칼리지파크에 있으며 워싱턴 D.C. 도심까지 대중교통으로 접근 가능한 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (45, 'University of Washington (Seattle)', '워싱턴 대학교 시애틀', 42, 3, null, null, null, null, null, null, '{"cs","engineering","business","math_data","natural_sci","arts"}', 'UW 입학처 공식 페이지는 표준화 시험 대신 교과 과정의 질(curriculum quality)과 과목 성적을 학업 평가의 중심에 둔다고 명시한다. 에세이와 과외활동을 포함한 지원서 전체를 개별 검토하는 홀리스틱 리뷰를 하며, 학업 외 성취와 지원자의 환경적 맥락도 함께 본다.', 'https://uw-s3-cdn.s3.us-west-2.amazonaws.com/wp-content/uploads/sites/162/2026/02/27111247/CDS_2025-2026_Seattle.pdf', 'test-free', '시애틀에 있는 워싱턴주 플래그십 주립대학으로 CS(Allen School)·공학·의생명 분야가 강한 대형 연구 중심 대학이다.', '워싱턴주 시애틀 도심 북쪽에 캠퍼스가 있으며 아마존·마이크로소프트 등 테크 기업 허브와 인접해 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (46, 'Lehigh University', '리하이 대학교', 46, 3, 1380, 1480, 'GPA 분포는 CDS에 미보고이며, 학급 석차 제출자(23%) 기준 상위 10% 이내 비율이 60%다 (CDS 2025-26 C10).', null, false, true, '{}', 'CDS 2025-26 C7 기준 Very Important는 교과 과정의 엄격성(rigor)과 GPA다. 지원자의 관심도(demonstrated interest)를 Important로 분류하는 드문 사립대라 캠퍼스 방문·정보 세션 등 관심 표시가 실제 평가에 반영되며, 에세이·추천서·과외활동도 Important로 고려된다.', 'https://data.lehigh.edu/sites/data.lehigh.edu/files/4.6.2026_CDS_Finalized-Published_Definition%20Sheet%20Removed%20for%20Website%20Posting_0.pdf', 'test-optional', '펜실베이니아주 베들레헴에 있는 사립 연구 중심 대학으로 공학과 비즈니스 프로그램의 명성이 높다.', '펜실베이니아주 베들레헴에 있으며 뉴욕과 필라델피아에서 각각 차로 약 1시간 30분 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (47, 'Northeastern University', '노스이스턴 대학교', 46, 3, 1450, 1520, 'GPA 제출자 기준 Fall 2024 신입생의 86.8%가 고교 GPA 4.0이다 (CDS 2024-25 C11).', null, null, true, '{}', 'CDS 2024-25 C7 기준 Very Important는 교과 과정의 엄격성(rigor), GPA, 표준화 시험 점수, 추천서 4가지다. 과외활동·재능·인성은 Important, 지원자의 관심도(demonstrated interest)와 에세이는 Considered로 반영된다.', 'http://uds.northeastern.edu/wp-content/uploads/2026/03/CDS-2024-25.pdf', 'test-optional', '보스턴에 있는 사립 연구 중심 대학으로, 기업 현장 근무를 학위과정에 결합한 코업(Co-op) 프로그램으로 유명하다.', '매사추세츠주 보스턴 도심에 캠퍼스가 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (48, 'Purdue University--Main Campus', '퍼듀 대학교', 46, 3, 1220, 1470, 'Fall 2025 신입생 평균 고교 GPA는 3.81이고, West Lafayette 캠퍼스 공식 프로필의 중간 50% GPA는 3.70-4.00이다 (CDS 2025-26 C12).', null, null, true, '{"cs","engineering","business","math_data","natural_sci","premed","social_sci","humanities","arts"}', 'CDS 2025-26 C7 기준 Very Important는 교과 과정의 엄격성(rigor), GPA, 에세이 3가지다. 공식 신입생 심사 기준 페이지는 ''지원 전공에서 성공할 수 있는 능력''과 해당 프로그램의 정원 상황을 심사 요소로 명시해, 전공 적합성이 합격에 직접 영향을 준다.', 'https://www.purdue.edu/idata/wp-content/uploads/2026/04/CDS-2025-2026.xlsx', 'test-required', '인디애나주 웨스트라피엣에 있는 공립 연구 중심 대학으로 공학·CS 등 STEM 분야의 명성이 높다.', '인디애나주 웨스트라피엣에 있으며 시카고에서 차로 약 2시간 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (49, 'University of Georgia', '조지아 대학교', 46, 3, 1220, 1400, 'Fall 2024 입학생 평균 고교 GPA 4.15(제출률 100%), 85.5%가 3.75 이상 (CDS 2024-25 C11-C12).', null, null, false, '{}', 'CDS 2024-25 C7에서 Very Important로 표시한 항목은 교과 이수의 엄격성(rigor)과 학업 GPA 두 가지이며, 표준화 시험 점수는 Important입니다. 공식 First-Year Criteria 페이지는 핵심 교과(영어·수학·과학·사회·외국어) 성적과 학교에서 제공되는 과목 대비 얼마나 도전적으로 수강했는지를 1차 기준으로 보고, 지적 탐구·리더십·봉사 등은 2차 요소로 검토한다고 명시합니다.', 'https://oir.uga.edu/wp-content/uploads/UGA_CDS_2024-2025.pdf', 'test-required', '1785년 설립된 미국 최초의 주립대학 중 하나로, 조지아주의 플래그십 공립 연구대학입니다.', '조지아주 애선스(Athens)에 위치하며 애틀랜타에서 차로 약 1시간 30분 거리입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (50, 'University of Rochester', '로체스터 대학교', 46, 3, 1420, 1500, 'Fall 2024 입학생 평균 고교 GPA 3.72(제출률 99.8%), 55.1%가 3.75 이상 (CDS 2024-25 C11-C12, AS&E 기준).', null, null, true, '{}', 'CDS 2024-25 C7 기준 Very Important 항목은 교과 rigor, 학업 GPA, 교외 활동(extracurricular activities), 인성/개인 자질(character) 네 가지입니다. 에세이·추천서·인터뷰·재능은 Important이며, 지원자의 관심 표현(demonstrated interest)도 Important로 반영되는 점이 특징입니다.', 'https://www.rochester.edu/provost/wp-content/uploads/2025/06/CDS_2024-2025-completed-for-web.pdf', 'test-optional', '뉴욕주 로체스터에 있는 사립 연구대학으로, 자유로운 커리큘럼과 이스트만 음악학교(Eastman School of Music)로 잘 알려져 있습니다.', '뉴욕주 서부 로체스터(Rochester)에 위치하며 뉴욕시에서 비행기로 약 1시간 거리입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (51, 'Case Western Reserve University', '케이스 웨스턴 리저브 대학교', 51, 3, 1440, 1530, 'Fall 2025 입학생 평균 고교 GPA 3.78(제출률 92%), 64.6%가 3.75 이상 (CDS 2025-26 C11-C12).', null, null, true, '{}', 'CDS 2025-26 C7 기준 Very Important 항목은 교과 rigor, 학급 석차(class rank), 학업 GPA, 교외 활동 네 가지입니다. 에세이·추천서·인터뷰·재능·인성·봉사활동은 Important이고, 지원자의 관심 표현은 Considered로 반영됩니다.', 'https://case.edu/ir/sites/default/files/2026-02/CDS%202025-26%20Adjusted%20Final.pdf', 'test-optional', '오하이오주 클리블랜드의 사립 연구대학으로 공학·의학·간호 등 STEM 분야가 강한 학교입니다.', '오하이오주 클리블랜드(Cleveland)의 University Circle 지구에 위치합니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (52, 'Florida State University', '플로리다 주립 대학교', 51, 3, 1360, 1470, 'Fall 2024 합격자 중간 50% 가중 GPA 4.2-4.6 (FSU 공식 Admissions Guide, 자체 재계산 가중 GPA 기준).', null, null, null, '{}', '공식 지원 페이지는 모든 지원자를 동일한 홀리스틱 절차로 심사하며 9-11학년 성적과 ACT/CLT/SAT 점수를 중심으로 본다고 명시합니다. 공식 Admissions Guide는 합격자 프로필로 가중 GPA 4.2-4.6, SAT 1360-1470을 제시해 교과 성적과 시험 점수가 핵심임을 보여줍니다.', 'https://admissions.fsu.edu/sites/g/files/upcbnu3881/files/PDF/2025/First-Year%20-%20How%20to%20Apply.pdf', 'test-required', '플로리다주의 대표 공립 연구대학 중 하나로, 주도 탤러해시에 메인 캠퍼스를 둔 대규모 주립대학입니다.', '플로리다주 주도 탤러해시(Tallahassee)에 위치합니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (53, 'Texas A&M University', '텍사스 A&M 대학교', 51, 3, 1160, 1390, 'CDS 2025-26에 GPA 분포는 미보고이며, Fall 2025 입학생 중 71.6%가 고교 상위 10%, 93.1%가 상위 25% 이내 (석차 제출 72.2%).', null, null, null, '{"engineering","cs"}', 'CDS 2025-26 C7 기준 Very Important 항목은 교과 rigor, 학급 석차, 학업 GPA, 교외 활동, 재능(talent/ability)입니다. 공식 신입생 지원 페이지는 텍사스 거주자 상위 10% 자동입학 외 지원자를 홀리스틱 심사하며, 학업 요소(수강 과목·성적·rigor·GPA·석차)와 비학업 요소(교외 활동·봉사·리더십·근로 경험)를 함께 본다고 명시합니다.', 'https://abpa.tamu.edu/_files/_documents/common-data/cds-pdf-2025-2026.pdf', 'test-optional', '텍사스주의 플래그십 공립 연구대학 중 하나로, 재학생 7만 명이 넘는 미국 최대 규모급 대학이며 공학 분야가 특히 큽니다.', '텍사스주 칼리지스테이션(College Station)에 위치하며 휴스턴에서 차로 약 1시간 30분 거리입니다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (54, 'Virginia Tech', '버지니아 공과대학교(버지니아텍)', 51, 3, null, null, '신입생 평균 고교 GPA 4.06 (제출률 96%, CDS 2023-24 C12, Fall 2023 입학생 기준).', null, null, false, '{"cs","engineering","business","math_data","natural_sci","premed","social_sci","humanities","arts"}', 'CDS 2023-24 C7 기준 Very Important 항목은 교과 이수 강도(rigor)·GPA·에세이·1세대 여부·거주지역/주 거주 여부다. 공식 입학요강은 학교 맥락 안에서의 교과 난이도, 성적 추이와 함께 ''지원 전공''을 명시적 평가 요소로 들며, 버지니아텍은 전공 단위로 심사한다.', 'https://www.vt.edu/admissions/undergraduate/apply/freshman-requirements.html', 'test-optional', '버지니아주의 대표 공립 공과계열 연구중심 대학으로 공학·컴퓨터과학 분야 규모가 크다.', '버지니아주 블랙스버그(Blacksburg)에 위치.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (55, 'Wake Forest University', '웨이크 포레스트 대학교', 51, 3, 1420, 1500, '평균 고교 GPA 미공시(CDS C12 무응답). 고교 내신 상위 10% 비율 64.2%(석차 제출자 18% 기준, C10).', null, false, true, '{}', 'CDS 2024-25 C7 기준 Very Important 항목은 교과 이수 강도(rigor)·내신 석차·GPA·에세이·인성(Character/personal qualities)이다. 표준화 시험 점수는 ''고려'' 수준이고 인터뷰·활동·재능은 Important로, 학업 기록과 글·인성을 중심으로 보는 학교다.', 'https://prod.wp.cdn.aws.wfu.edu/sites/202/2025/07/CDS-2024-2025-fillable-WFU.pdf', 'test-optional', '소규모 학부 교육과 낮은 학생 대 교수 비율을 강조하는 노스캐롤라이나의 사립 연구대학이다.', '노스캐롤라이나주 윈스턴세일럼(Winston-Salem)에 위치.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (56, 'William & Mary', '윌리엄 앤 메리 대학교', 51, 3, 1390, 1520, '평균 고교 GPA 4.34(가중 척도, 제출률 88%), 4.0 이상 비율 88.9%, 고교 상위 10% 이내 79%(석차 제출자 30% 기준). CDS 2025-26.', null, null, true, '{}', 'CDS 2025-26 C7 기준 Very Important 항목이 매우 넓다: 교과 이수 강도·내신 석차·GPA·에세이·추천서·교내외 활동·재능·인성·주(州) 거주 여부·봉사·직업 경험. 학업 기록과 함께 활동·인성·글을 폭넓게 종합 평가하는 공립 리버럴아츠형 대학이다.', 'https://www.wm.edu/offices/ir/university_data/cds/cds_2025-26_c1.pdf', 'test-optional', '1693년 설립된 미국에서 두 번째로 오래된 대학으로 ''퍼블릭 아이비''로 불리는 버지니아 공립대학이다.', '버지니아주 윌리엄스버그(Williamsburg)에 위치.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (57, 'University of California, Merced', '캘리포니아 대학교 머세드(UC 머세드)', 57, 3, null, null, '합격자 고교 GPA 중간 50% 구간 3.57-4.16 (Fall 2026 지원 주기, UC 공식 신입생 admit data). 최소 요건: GPA 3.0(캘리포니아 거주자), 3.4(비거주자·국제).', null, null, false, '{}', 'UC 공식 요건 기준 시험 점수 없이 종합심사로 평가한다: A-G 15개 대학예비과목 이수와 GPA(최소 3.0, 비거주자 3.4)가 기본 요건이다(UC 신입생 요건 페이지). UC Merced 공식 요강도 교과 이수와 GPA 중심의 요건만 명시하며 SAT/ACT는 입학·장학 어디에도 반영하지 않는다.', 'https://admissions.ucmerced.edu/first-year/requirements', 'test-free', '2005년 개교한 UC 시스템의 최신 캠퍼스로, 규모는 작지만 R1 연구대학 지위를 가진 공립대학이다.', '캘리포니아주 센트럴밸리의 머세드(Merced)에 위치.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (58, 'Villanova University', '빌라노바 대학교', 57, 3, 1420, 1490, '평균 고교 GPA 3.87, 고교 상위 10% 이내 81%(석차 제출자 19% 기준). CDS 2025-26, Fall 2025 입학생.', null, false, false, '{"business","engineering","premed"}', 'CDS 2025-26 C7 기준 Very Important 항목은 교과 이수 강도(rigor)·GPA·에세이 세 가지다. 추천서·활동·재능·인성·봉사는 Important이고, 지원 관심도(demonstrated interest)와 인터뷰는 반영하지 않는다. 학업 기록과 에세이 중심의 심사다.', 'https://www.villanova.edu/content/dam/villanova/provost/decision_support/CDS-2025-2026-v3.pdf', 'test-optional', '아우구스티노 수도회 전통의 가톨릭 사립대학으로 경영·공학·간호 학부가 강한 편이다.', '펜실베이니아주 필라델피아 근교 빌라노바(Villanova)에 위치.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (59, 'George Washington University', '조지워싱턴 대학교', 59, 3, 1310, 1450, '평균 GPA는 CDS 미공개, 석차 제출자(20.8%) 중 고교 상위 10% 이내 44% (2025-26 CDS C10)', 36.3, false, true, '{"cs","engineering","business","social_sci","arts","premed"}', '2025-26 CDS C7 기준 ''교과 과정의 엄격성(rigor)''과 ''GPA'' 두 가지만 Very Important이고 에세이·추천서는 Important다. 공식 입학처 Test Optional 페이지는 ''고교에서 받은 성적과 수강 과목의 난도가 GW 평가에서 항상 가장 중요한 부분''이라고 명시한다. 지원자의 관심도(demonstrated interest)도 Considered로 반영된다.', 'https://irp.gwu.edu/sites/g/files/zaxdzs6056/files/2026-04/CDS-PDF-2025-2026.pdf', 'test-optional', '워싱턴 D.C. 도심에 위치한 사립 종합대학으로 국제관계·정치·정책 분야 프로그램으로 잘 알려져 있다.', '워싱턴 D.C. Foggy Bottom 캠퍼스로 백악관·국무부 등과 도보 거리에 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (60, 'Pennsylvania State University--University Park', '펜실베이니아 주립대학교 유니버시티 파크', 59, 3, 1250, 1410, '신입생 평균 고교 GPA 3.84 (Fall 2024, 제출률 95.2%, 2024-25 CDS C12)', 64.4, false, false, '{}', '2024-25 CDS C7 기준 Academic GPA가 유일한 Very Important 요소이고 교과 엄격성은 Important, 에세이·추천서·과외활동은 Not Considered다. CDS C6에는 ''펜스테이트 입학은 학업 성취(academic credentials) 기반의 경쟁 선발''이라고 명시돼 있다. 시험 미제출자는 지망 전공 관련 교과 성적을 중점 평가한다고 공식 발표에서 밝혔다.', 'https://opair.psu.edu/files/2025/04/CDS_2024_2025_University_Park1.pdf', 'test-optional', '펜실베이니아주의 대표 주립대학으로, University Park가 메인 캠퍼스이며 학부 규모가 미국 최대급이다.', '펜실베이니아주 중부의 대학 도시 스테이트 칼리지(State College)에 위치한다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (61, 'Santa Clara University', '산타클라라 대학교', 59, 3, 1330, 1470, '신입생 평균 고교 GPA 3.72 (Fall 2025, 제출률 100%, 2025-26 CDS C12)', 28.6, false, true, '{"business","engineering"}', '2024-25 CDS C7 기준 학업 요소로는 교과 엄격성·GPA·에세이가, 비학업 요소로는 과외활동·재능·인성·봉사·직무경험이 모두 Very Important로 표시된 폭넓은 종합평가다. 지원자의 관심도(demonstrated interest)도 Important로 반영된다. 지원 시 3개 스쿨 중 하나를 선택해 해당 스쿨 기준으로 평가받는다(공식 입학처).', 'https://www.scu.edu/media/offices/institutional-research/fampf/common-data-set/rba13-Common_Data_Set_2025-2026.pdf', 'test-optional', '실리콘밸리에 위치한 예수회(Jesuit) 사립대학으로 학부 중심 교육과 테크 업계 접근성이 특징이다.', '캘리포니아주 산타클라라, 실리콘밸리 중심부에 캠퍼스가 있다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (62, 'Stony Brook University (SUNY)', '스토니브룩 대학교 (뉴욕주립대)', 59, 3, 1350, 1470, '평균 고교 성적 94.48/100점(100점 스케일 보고), GPA 4.0 비율 45% (Fall 2025, 2025-26 CDS C11-C12)', 67.1, null, true, '{"cs","engineering"}', '2025-26 CDS C7 기준 교과 엄격성, GPA, 표준화 시험 점수, 에세이가 Very Important이고 추천서는 Important다. 과외활동·인성 등 대부분의 비학업 요소는 Considered 수준으로, 학업 지표 중심의 평가 구조다.', 'https://www.stonybrook.edu/irpe/_media/Common_data_sets/CDS_2025-2026.xlsx', 'test-optional', '뉴욕주립대(SUNY) 소속의 연구 중심 대학으로 AAU 회원교이며 이공계 프로그램이 강하다.', '뉴욕주 롱아일랜드 스토니브룩에 위치하며 맨해튼에서 동쪽으로 약 100km 거리다.');
insert into schools (id, name, name_ko, usnews_rank, tier, sat_mid50_low, sat_mid50_high, gpa_note, intl_accept_rate, need_blind_intl, demonstrated_interest, direct_admit_majors, what_they_value, source_url, test_policy, intro_ko, location_note) values (63, 'University of Minnesota, Twin Cities', '미네소타 대학교 트윈시티', 59, 3, 1320, 1470, '평균 GPA는 CDS 미공개, 석차 제출자(38.4%) 중 고교 상위 10% 이내 36.3% (Fall 2024, 2024-25 CDS C10)', 82.1, null, false, '{"cs","engineering","math_data","business","natural_sci","premed","arts"}', '공식 입학처는 자동 컷오프 없는 holistic review를 하되 ''대학 성공의 가장 큰 예측 요인은 학업 준비도''라며 고교 성적 기록에 가장 강한 비중을 둔다고 명시한다. 2024-25 CDS C7 기준 교과 엄격성·석차·GPA가 Very Important다. 학업 외 요소(재능·봉사·극복 경험 등)는 맥락(context) 요소로 함께 고려된다.', 'https://idr.umn.edu/sites/idr.umn.edu/files/cds_2024_2025_tc_1.pdf', 'test-optional', '미네소타주의 대표 주립 연구대학으로 미니애폴리스·세인트폴 두 도시에 걸친 대형 캠퍼스를 운영한다.', '미네소타주 미니애폴리스와 세인트폴(트윈시티)에 캠퍼스가 있다.');
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (1, '4년 과목 플랜 짜기 — 수학 트랙부터 확인', '12학년까지 Calculus 도달 경로가 여기서 결정됨 — 학교 수학 시퀀스를 확인하고, 경로가 안 나오면 여름 보강 계획을 지금 세울 것', 9, 'fall', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (2, 'GPA 루틴 만들기', '9학년 성적도 GPA에 그대로 들어감 — 과제·시험 준비 루틴은 첫 학기에 잡는 게 가장 쉽고, 상승 곡선의 시작점이 됨', 9, 'fall', null, null, false, false, 'rigor', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (3, '성격이 다른 활동 2~3개 시도', '지금은 잘하는 것보다 계속하고 싶은 걸 찾는 시기 — 만들기형·사람형·쓰기형처럼 유형을 다르게 골라볼 것', 9, 'fall', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (4, '학교의 국제 인증(WASC·Cognia 등)과 school profile 존재 확인', '성적표의 대외 신뢰도를 좌우하는 정보 — 학교 행정실에 직접 물어보고, 없다면 AP·SAT 등 외부 지표 비중을 높이는 전략으로', 9, 'fall', null, null, false, true, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (5, '영어 노출량 늘리기 (시험 말고 기반)', 'TOEFL은 아직 멀었음 — 지금은 관심 분야의 영어 콘텐츠를 일상으로 소비하는 습관이 나중의 점수를 만듦', 9, 'fall', null, null, true, false, 'testing', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (6, '10학년 과목 신청 — Honors 도전 포함', '리거는 학년마다 한 계단씩 올라가는 그림이 이상적 — 감당 가능한 선에서 Honors를 1~2개 넣을 것', 9, 'spring', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (7, '시도한 활동 거르기 — 계속할 것만 남기기', '전부 유지하면 전부 얕아짐 — "다음 학기에도 하고 싶은가"로 판단해 2개 이내로', 9, 'spring', null, null, false, false, 'spike', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (8, '여름 계획 세우기', '9학년 여름은 부담 없는 탐색이 정답 — 무료·자기주도 활동 하나면 충분하고, 비싼 캠프가 필요한 시기가 아님', 9, 'spring', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (9, '첫해 성적 점검 — 약한 과목 보강 계획', 'AO는 추세를 봄 — 9학년에 흔들린 과목은 10학년 상승으로 덮을 수 있으니 지금 원인을 찾을 것', 9, 'spring', null, null, false, false, 'rigor', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (10, '관심 분야 탐색 활동 1개 실행', '결과물이 없어도 됨 — "이 분야가 나랑 맞는지" 확인이 이번 여름의 목표', 9, 'summer', null, null, false, false, 'spike', true, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (11, '관심 분야 독서·기록 습관', '읽고 남긴 기록이 나중에 에세이 재료가 됨 — 짧은 감상이라도 남길 것', 9, 'summer', null, null, false, false, 'story', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (12, 'PSAT 연습 응시', '점수가 아니라 형식 경험이 목적 — 실전 감각은 한 번의 경험으로 크게 달라짐', 10, 'fall', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (13, '첫 AP/Honors 과목 안착', '어려워진 과목에서 성적을 지키는 게 이번 학기 최우선 — 리거 상승과 GPA 유지를 동시에 잡는 연습', 10, 'fall', null, null, false, false, 'rigor', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (14, '활동 몰입 시작 — 넓히는 시기는 끝', '이제부터는 남긴 활동을 깊게 파는 구간 — 새 활동 추가는 기존 것과 연결될 때만', 10, 'fall', null, null, false, false, 'spike', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (15, '추천서 후보 교사와 수업 안에서 신뢰 쌓기', '추천서는 벼락치기가 안 됨 — 11학년에 부탁할 교사 후보를 정하고 질문·참여로 기억에 남는 학생이 될 것', 10, 'fall', null, null, false, true, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (16, '11학년 AP 라인업 확정', 'AP는 전년도에 신청함 — 전공 관련 핵심 AP가 포함됐는지, 미개설이면 자습 응시 계획까지 이번 달에 결정', 10, 'spring', null, null, false, false, 'rigor', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (17, 'AP 시험 응시 (수강 중이라면)', '첫 AP 점수는 실전 리허설 — 5점이면 좋지만 시험 운영 경험 자체가 11학년 다과목 시즌의 자산', 10, 'spring', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (18, 'SAT 공부 시작 시점 결정', '표준 리듬은 10학년 여름 시작 → 11학년 가을 1차 응시 — 목표 티어가 높을수록 이 리듬을 지킬 것', 10, 'spring', null, null, false, false, 'testing', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (19, '여름 심화 활동 확정', '10학년 여름은 스파이크 만들기의 마지노선 — 프로젝트·리서치·봉사 중 하나를 구체적 계획으로', 10, 'spring', null, null, false, false, 'spike', true, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (20, '심화 활동 착수', '참가가 아니라 만들기 — 여름이 끝날 때 "보여줄 수 있는 것"이 하나 남는 걸 목표로', 10, 'summer', null, null, false, false, 'spike', true, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (21, 'SAT 기초 학습 시작', '진단 모의고사로 시작점 확인 → 약점 영역 중심 학습 — 무료 공식 자료(Khan Academy)로 충분한 단계', 10, 'summer', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (22, 'TOEFL 필요 여부 판단', '목표 학교마다 면제 기준이 다름 — 국제학교 재학 연수로 면제되는 학교도 있으니 목표 리스트 기준으로 확인 후 계획', 10, 'summer', null, null, true, false, 'testing', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (23, 'PSAT 실전 응시', '11학년 PSAT는 실전 — SAT 직전 리허설이자 현재 위치 확인', 11, 'fall', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (24, 'SAT 1차 응시 등록·응시', '가을 1차 → 봄 재응시가 표준 — 1차를 미루면 재응시 기회가 사라짐, 응시 장소는 미리 확보', 11, 'fall', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (25, 'AP 다과목 관리 루틴 세우기', '11학년은 최대 하중의 해 — 과목별 주간 루틴 없이는 전 과목이 같이 흔들림', 11, 'fall', null, null, false, false, 'rigor', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (26, '리더십 포지션 확보 또는 직접 만들기', 'AO는 직함보다 만든 것을 봄 — 기존 클럽 임원이 어려우면 작게라도 직접 만들 것', 11, 'fall', null, null, false, false, 'leadership', true, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (27, '외부 검증 도전 — 대회·투고 마감 확인', '원서에 들어갈 수확의 마지막 해 — 지금 마감 캘린더를 만들어야 봄의 기회를 놓치지 않음', 11, 'fall', null, null, false, false, 'validation', true, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (28, '추천서 교사 2명 내정', '12학년 가을에 부탁하면 늦음 — 지금부터 그 수업에서 추천서에 쓸 재료(질문·프로젝트·성장)를 만들 것', 11, 'fall', null, null, false, true, 'story', false, 60);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (29, 'SAT 재응시·마무리', '봄 안에 끝내는 게 목표 — 여름·가을은 에세이와 원서의 시간', 11, 'spring', null, null, false, false, 'testing', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (30, 'AP 시험 시즌 운영', '다과목 시험은 체력전 — 과목별 우선순위를 정하고 전공 관련 과목에 5점을 집중', 11, 'spring', null, null, false, false, 'testing', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (31, '대학 리스트 초안 만들기', 'reach/match/safety 균형이 핵심 — 툴의 둘러보기와 내 위치 마커로 각 그룹 3~4개씩', 11, 'spring', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (32, 'TOEFL 마무리', 'SAT와 원서가 몰리기 전에 끝낼 것 — 여름 이후로 밀리면 일정이 겹침', 11, 'spring', null, null, true, false, 'testing', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (33, '추천서 공식 부탁', '학년이 끝나기 전 부탁이 예의이자 안전 — 교사가 여름에 쓸 시간을 확보해주는 것', 11, 'spring', null, null, false, false, 'story', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (34, '원서 메인 에세이 초안 완성', '12학년 가을엔 쓸 시간이 없음 — 여름 초안, 가을 퇴고가 표준 리듬', 11, 'summer', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (35, '대표 활동 마무리·정리', '스파이크를 "보여줄 수 있는 형태"로 — 결과물·숫자·기록을 지금 정리해야 활동란이 쉬워짐', 11, 'summer', null, null, false, false, 'spike', true, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (36, '대학 리스트 확정 + ED/EA 전략 결정', 'ED는 합격 시 등록 의무가 있는 카드 — 진짜 1지망과 재정 조건을 함께 고려해 결정', 11, 'summer', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (37, '재정 서류 준비 논의 시작', '은행잔고증명 등은 부모님과 시간이 필요한 서류 — need-aware 학교 지원 전략과도 연결되니 여름에 논의 시작', 11, 'summer', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (38, 'Common App 계정 생성·활동란 초안', '활동란 10칸은 생각보다 오래 걸림 — 각 활동을 150자로 압축하는 연습을 지금', 11, 'summer', null, null, false, false, 'story', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (39, 'ED/EA 원서 제출 — 마감 역산 관리', '마감일이 아니라 발송 완료일 기준으로 역산 — 추천서·성적표는 내가 아니라 남이 보내는 것이므로 여유가 필수', 12, 'fall', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (40, '메인 에세이 완성 + 보충 에세이 착수', '보충 에세이가 진짜 분량 — 학교별 문항을 스프레드시트로 정리하면 겹치는 주제를 재활용할 수 있음', 12, 'fall', null, null, false, false, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (41, '성적표·추천서 발송 확인 — 담당자 직접 지정', '전담 카운슬러가 없으면 발송 주체가 불분명해짐 — 누가 언제 보내는지 이름과 날짜로 확정할 것', 12, 'fall', null, null, false, true, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (42, 'CSS Profile·재정증명 제출', '재정지원 서류는 원서와 마감이 다름 — 학교별 요구 서류와 마감을 따로 관리', 12, 'fall', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (43, '12학년 성적 유지', '합격 취소 사유 1위가 성적 급락 — 원서 시즌에도 수업은 평가되고 있음', 12, 'fall', null, null, false, false, 'rigor', false, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (44, 'RD 결과 정리·비교표 만들기', '감정이 아니라 조건으로 비교 — 학비·재정지원·전공 조건을 한 표에 놓고 볼 것', 12, 'spring', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (45, '재정지원 오퍼 검토·이의신청 확인', '오퍼는 협상 여지가 있는 경우가 있음 — 다른 학교 오퍼가 근거가 되기도 함', 12, 'spring', null, null, true, false, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (46, '최종 선택·디파짓', '등록 의사 마감일 확인 — 복수 디파짓은 원칙 위반이니 하나만', 12, 'spring', null, null, false, false, 'story', false, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (47, 'I-20 신청·비자 인터뷰 준비', '합격 확정 즉시 시작 — 여름엔 인터뷰가 몰려서 늦으면 출국 일정이 위험해짐', 12, 'spring', null, null, true, false, 'story', false, 40);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (48, '웨이트리스트 대응 (해당 시)', '관심 유지 편지(LOCI)는 새로운 업데이트가 있을 때만 효과 — 형식적 편지는 무의미', 12, 'spring', null, null, false, false, 'story', true, 50);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (49, '입학 준비 — 기숙사·오리엔테이션·수강신청', '입학처 이메일이 여름 내내 옴 — 놓치면 불이익이 실제로 있으니 주 1회 메일 점검 루틴', 12, 'summer', null, null, false, false, 'story', false, 10);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (50, '최종 성적표 발송 확인', '발송 주체를 지정하고 도착까지 확인 — 이게 마지막 서류', 12, 'summer', null, null, false, true, 'story', false, 20);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (51, '활동·툴 인수인계', '만든 것이 남으면 그게 legacy — 후배에게 자료·계정·노하우를 넘기고 기록으로 남길 것', 12, 'summer', null, null, false, false, 'leadership', true, 30);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (52, '파이썬 기초 + 첫 미니 프로젝트', '튜토리얼 따라하기 졸업이 목표 — 결과물이 남는 개인 프로젝트가 CS 스파이크의 시작', 9, 'summer', 'cs', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (53, 'AP CS A 수강 또는 자습 시작', '전공 직결이고 자습 난도가 낮은 편이라 자습 응시 1순위 후보 — 미개설이어도 포기할 이유가 없음', 10, 'fall', 'cs', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (54, '깃허브 포트폴리오 개설 — 프로젝트 1개를 배포 상태로', '"사용자가 있는가"가 프로젝트의 급을 나눔 — 미완성 프로젝트 개수 늘리기가 가장 흔한 함정', 10, 'fall', 'cs', null, false, false, 'spike', true, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (55, 'USACO Bronze 첫 응시', '무료·온라인·국제학생 응시 가능 — 부담 없이 수준 파악이 목적', 10, 'fall', 'cs', null, false, false, 'validation', true, 130);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (56, '11학년 AP 라인업에 Calc(BC 가능하면 BC)와 CS A 포함 확정', '학교 미개설 시 자습 응시 계획을 이번 달에 세울 것 — 비인가 국제학교는 AP 응시 장소 확보를 11학년 가을 전에 확인', 10, 'spring', 'cs', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (57, '목표 학교 CS direct-admit 여부 전수 확인', 'CS는 다수 학교가 전공 단위 선발이며 경쟁률이 학교 전체 합격률보다 훨씬 높고 전과도 어려움 — 선발 방식 확인이 필수', 11, 'fall', 'cs', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (58, 'AP Physics 여력 검토', '공학 계열 신뢰도 보강 — Calc BC 다음 순위', 11, 'fall', 'cs', null, false, false, 'rigor', false, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (59, 'USACO 승급 도전 또는 해커톤·제출형 대회 1개', '원서에 들어갈 수확의 해 — 유료 코딩캠프 수료증을 성과로 착각하는 것이 함정', 11, 'spring', 'cs', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (60, '대표 프로젝트에 실사용자 만들기', '배포된 앱/웹과 사용자 숫자가 활동란의 핵심 재료 — 새 프로젝트보다 기존 것의 심화', 11, 'summer', 'cs', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (61, '포트폴리오 링크 정리 — README·데모 영상', '원서 Additional Info에 기술 스택 요약까지 준비하면 활동란이 살아남', 12, 'fall', 'cs', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (62, '만들기 입문 — 아두이노·3D프린팅·조립 프로젝트', '과정 기록(빌드로그)이 결과물만큼 중요 — 기록 습관을 처음부터', 9, 'summer', 'engineering', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (63, '로봇 팀 합류 — 학교에 없으면 창설 준비', 'FTC/VEX 등 — 팀이 없으면 창설 자체가 리더십 스토리', 10, 'fall', 'engineering', null, false, false, 'leadership', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (64, '11학년 AP Physics(방향 맞게 C 또는 1) + Calc BC 라인업 확정', '세부 방향에 맞춰 1개를 확실히 — 화공이면 Chemistry 우선', 10, 'spring', 'engineering', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (65, 'Calc BC + Physics C(또는 Chem) 동시 수행 루틴 잡기', '이 전공 최대 하중의 해 — 과목별 주간 루틴 없이는 전 과목이 같이 흔들림', 11, 'fall', 'engineering', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (66, '팀에서 명확한 담당 파트 확보 — 설계/코딩/구동 등', '팀 대회에서 역할 불명확("팀원1")이 함정 — 자기 담당 파트를 말할 수 있어야 함', 11, 'fall', 'engineering', null, false, false, 'leadership', true, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (67, 'F=ma·물리 경시 또는 Science Olympiad 응시', '원서에 들어갈 외부 검증의 마지막 수확 시즌', 11, 'spring', 'engineering', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (68, '개인 제작물 1개 완성', '참가가 아니라 만들기 — 사진·빌드로그·결과가 남는 걸 목표로', 11, 'summer', 'engineering', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (69, '제작물 포트폴리오 정리 — 사진·빌드로그·결과', '대회 결과와 함께 원서에 반영', 12, 'fall', 'engineering', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (70, '작은 실전 경험 시작 — 교내 판매·펀드레이징 참여', '실제 돈·고객·결과가 있는 것으로 감 잡기 — 직함보다 실행', 9, 'fall', 'business', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (71, 'DECA/FBLA 챕터 확인 — 없으면 창설 추진', '챕터 창설이 참가보다 큰 스토리', 10, 'fall', 'business', null, false, false, 'leadership', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (72, 'AP Econ(Micro/Macro) 수강·자습 계획 + 11학년 Calc 신청 확정', '전공 직결 세트이고 자습 난도도 낮은 편 — 경제학은 수학 전공에 가깝다는 게 상위권 대학 시각, BC면 더 좋음', 10, 'spring', 'business', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (73, '실전 프로젝트 기획·착수 — 실제 돈·고객이 있는 것', '"창업 동아리 부원"처럼 실행 없는 직함이 함정 — 매출 1만 원이라도 실제 숫자가 있는 활동이 이김', 10, 'summer', 'business', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (74, 'Wharton 투자대회 등 팀 대회 출전', '무료·온라인·팀 단위 — 마감 캘린더를 미리 확인', 11, 'fall', 'business', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (75, 'AP Statistics·English Language 라인업 확인', '케이스 분석·에세이 비중이 높은 전공 특성', 11, 'spring', 'business', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (76, '운영 프로젝트의 숫자 만들기 — 매출·사용자·성장률', '정량 기록이 있어야 원서에서 실행이 증명됨', 11, 'summer', 'business', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (77, '프로젝트 결과 정량화해 원서 반영 + 후계자 지정', '"매출 X원, 고객 Y명" — 후계자 지정으로 지속성까지 증명', 12, 'fall', 'business', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (78, 'AMC 8/10 첫 응시', '수준 파악용 — 국제학생 응시 가능, 응시처는 미리 확보', 9, 'fall', 'math_data', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (79, '수학 동아리 활동 시작', '트랙 자체가 스펙인 전공 — 같이 문제를 푸는 환경 만들기', 9, 'fall', 'math_data', null, false, false, 'spike', true, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (80, 'AMC 10/12 재응시 — AIME 컷 도전', '점수가 안 나온다고 전공을 접는 게 함정 — 경시는 여러 경로 중 하나, 프로젝트·리서치 경로도 동등하게 유효', 10, 'fall', 'math_data', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (81, '11학년 Calc BC 신청 확정 + AP Statistics 병행 검토', '이 전공에서 AB 멈춤은 감점 신호에 가까움', 10, 'spring', 'math_data', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (82, '첫 데이터 프로젝트 — 실데이터 분석 1건', '결과물이 남는 리포트로 — 데이터 방향이면 CS A도 필수급', 10, 'summer', 'math_data', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (83, '수학 튜터링·교육 콘텐츠 제작 시작', '리더십 축을 확보하는 이 전공의 대표 경로', 11, 'fall', 'math_data', null, false, false, 'leadership', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (84, 'AIME 도전 또는 Kaggle·데이터 대회', 'AIME는 봄 — 원서 수확의 마지막 시즌', 11, 'spring', 'math_data', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (85, '학교 수학 소진 시 이후 과정(멀티변수 등) 온라인 수강 계획', '학교 과정을 다 소진했다면 그 이후를 스스로 이어가는 게 스파이크', 11, 'spring', 'math_data', null, false, false, 'rigor', false, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (86, '프로젝트·경시 실적 정리 — 리서치는 학생 저널 투고 마무리', '수확을 원서 형식으로 변환하는 시기', 12, 'fall', 'math_data', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (87, '과학 기초 3과목 성실히 — 방향은 아직 안 정해도 됨', '과학 동아리·교내 실험·다큐로 방향을 찾는 탐색기', 9, 'fall', 'natural_sci', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (88, 'Science Olympiad·교내 사이언스페어 참가', '교내→지역→국제로 이어지는 검증 라인의 시작', 10, 'fall', 'natural_sci', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (89, '전공 방향 확정 → 11학년 해당 AP 과학 신청', '본인 방향 1개는 반드시 — 물리·화학은 Calc BC 권장, 생물은 AB+Statistics 조합도 유효', 10, 'spring', 'natural_sci', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (90, '자가 설계 실험·데이터 수집 프로젝트 시작', '거창한 랩이 아니어도 됨 — 문헌 리뷰도 시작점으로 유효', 10, 'summer', 'natural_sci', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (91, '리서치 심화 — 지역 사이언스페어 출품 또는 학생 저널(JEI 등) 투고', '투고는 비용 거의 0에 결과물이 남는 최고 가성비 경로 — "프로그램 수료" 자체를 성과로 쓰는 게 함정', 11, 'spring', 'natural_sci', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (92, '인접 과학 AP 추가 검토', '예: 생물 전공이면 화학 — 이중 축이 신뢰도를 만듦', 11, 'spring', 'natural_sci', null, false, false, 'rigor', false, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (93, '리서치 결과물 마무리 — 게재·출품 결과 원서 반영', '뭘 발견/제작했는지가 핵심 — 수료증이 아니라 결과물', 12, 'fall', 'natural_sci', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (94, '정기 봉사처 확보 — 지속 가능한 곳으로', '요양시설·복지관 등 — 2주 이벤트가 아니라 2년 루틴 설계, 1회성 의료 미션이 함정', 9, 'fall', 'premed', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (95, '봉사 역할 성장 — 참여자→기획자 + HOSA 챕터 확인·창설 검토', 'AO는 2주 해외 봉사보다 2년 주말 봉사를 높게 봄 — 역할의 성장이 서사', 10, 'fall', 'premed', null, false, false, 'leadership', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (96, '11학년 AP Bio 또는 Chem 신청 확정', '프리메드 이중 필수축 — 하나는 11학년에 반드시', 10, 'spring', 'premed', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (97, 'AP Psychology·Statistics 보강 검토', '보건 계열 관련성 + 의학 연구 기초 — 부담 대비 가치가 높음', 11, 'fall', 'premed', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (98, '보건 주제 리서치 또는 캠페인 조직', '헌혈 캠페인·보건 교육 콘텐츠가 한국에서 현실적인 대안', 11, 'spring', 'premed', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (99, '봉사 누적 시간·기록 정리', '숫자와 기록이 있어야 활동란이 쉬워짐', 11, 'summer', 'premed', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (100, '봉사 서사 정리 — 시간 수가 아니라 "왜 계속했는가"', '이 트랙은 성적 일관성이 생명 — GPA 방어와 병행', 12, 'fall', 'premed', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (101, 'MUN·토론 첫 참가 + 관심 이슈 정하기', '수준 파악이 목적 — 이슈 하나를 정하면 이후 활동이 연결됨', 9, 'fall', 'social_sci', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (102, '관심 이슈 콘텐츠 제작 개시 — 블로그·뉴스레터', '장기 운영의 누적 기록이 스파이크 — 시사 분석을 일상으로', 10, 'fall', 'social_sci', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (103, '11학년 방향 AP(Psych/Gov/History) 신청 확정 + Statistics 검토', '사회과학=데이터 학문이라는 인식을 보여주는 선택', 10, 'spring', 'social_sci', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (104, 'MUN 의장단·운영진 도전', '참가 횟수 나열이 함정 — 역할의 성장(대표→의장→운영)이 서사', 11, 'fall', 'social_sci', null, false, false, 'leadership', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (105, '에세이 대회(John Locke 등) 출품 또는 자체 설문 연구 수행', '질문을 파고든 흔적이 이 전공의 검증', 11, 'spring', 'social_sci', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (106, '장기 운영 콘텐츠의 누적 기록 정리 — 발행 횟수·구독자', '숫자로 남긴 지속성이 원서 재료', 12, 'fall', 'social_sci', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (107, '교지·문예지 활동 시작 — 없으면 창간 검토', '창간이 최고의 스토리 — 쓰기의 몸체를 만드는 시작점', 9, 'fall', 'humanities', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (108, '장기 집필 프로젝트 시작 — 소설·논픽션·비평 연재', '"독서를 많이 함"은 활동이 아님 — 읽은 것이 쓴 것으로 변환된 증거가 필요', 10, 'fall', 'humanities', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (109, '첫 글쓰기 대회 출품', 'Scholastic은 가을 마감 — 국제학생 참가 가능 여부는 사전 확인', 10, 'fall', 'humanities', null, false, false, 'validation', true, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (110, '11학년 AP English Lang + History 신청 확정 — 수학도 AB 라인 유지', '상위권 대학은 인문 지원자에게도 수학 리거를 봄 (최소 AB 권장)', 10, 'spring', 'humanities', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (111, 'Scholastic·John Locke 등 대회 본격 출품', '문학 저널 투고도 병행 — 수확의 해', 11, 'fall', 'humanities', null, false, false, 'validation', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (112, '집필 프로젝트 완성 또는 문예지 편집장', '완성작 하나 또는 이끄는 역할 하나 — 둘 중 하나는 이번 해에', 11, 'spring', 'humanities', null, false, false, 'leadership', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (113, '대표작 완성 — 원서 보충 자료·에세이의 원천', '역사 방향이면 The Concord Review 도전 검토 (최상위 난도)', 12, 'fall', 'humanities', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (114, '작품을 "많이" 만드는 해 — 스타일 실험·스케치북 습관', '지금은 양이 질을 만드는 시기', 9, 'fall', 'arts', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (115, '포트폴리오용 작품 축적 공식 시작', '입시 직전 학원식 급조 포트폴리오가 함정 — 미국 미대는 기술 완성도보다 관점의 일관성을 봄', 10, 'fall', 'arts', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (116, 'Scholastic 등 첫 공모 출품', '가을 마감 — 첫 외부 노출 경험', 10, 'fall', 'arts', null, false, false, 'validation', true, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (117, 'AP Art History 또는 코어 AP 계획', '종합대학 미대는 학업도 봄 — 코어 GPA 방어 라인 유지', 10, 'spring', 'arts', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (118, 'AP Art & Design 착수 — 제출 포트폴리오와 연동', '포트폴리오 제출 구조라 그 자체가 작품 축적 과정', 11, 'fall', 'arts', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (119, '작품 세계관 좁히기 — 일관된 주제 시리즈 제작', '흩어진 잘 그린 그림보다 하나의 관점이 강함', 11, 'spring', 'arts', null, false, false, 'spike', true, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (120, '교내 전시 기획', '리더십 + 작품 노출의 이중 효과', 11, 'spring', 'arts', null, false, false, 'leadership', true, 120);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (121, '학교별 포트폴리오 요강 전수 확인 + 지원용 15~20점 완성', '요강이 학교마다 다름 — 여름부터 편집한 것을 마감 전 확정', 12, 'fall', 'arts', null, false, false, 'story', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (122, '11학년 AP는 "어느 전공에도 통하는 조합"으로 — Calc + Eng Lang + 과학 1 + 역사 1', '미정일수록 몰빵보다 코어 리거 균형 — "미정=대충"이 아니라 각 코어에서 학교가 주는 최고 난도를 잡는 것', 10, 'spring', 'undecided', null, false, false, 'rigor', false, 110);
insert into checklist_items (id, title, why_how, grade, season, major_category, tier_condition, intl_only, no_counselor_only, axis, is_guide, sort_order) values (123, '활동 1~2개로 압축 + 전공 방향 재설정', '좁히는 시점을 놓치면 스파이크 만들 시간이 사라짐 — 툴에서 전공을 다시 골라보는 것도 이번 시즌', 10, 'spring', 'undecided', null, false, false, 'spike', true, 120);
